def mk(prefix, start):
    n = [start]
    def nid():
        n[0] += 1
        return f"secai-plus.{prefix}.q{n[0]:03d}"
    def base(lesson, obj, diff, typ, case=None):
        return {"id": nid(), "lesson": f"secai-plus.{lesson}", "objective": obj, "difficulty": diff, "type": typ, "case": case}
    def S(lesson, obj, diff, stem, opts, ans, ex, case=None):
        return {**base(lesson, obj, diff, "single", case), "stem": stem, "options": opts, "answer": [ans], "explain": ex}
    def M(lesson, obj, diff, stem, opts, ans, ex, case=None):
        return {**base(lesson, obj, diff, "multi", case), "stem": stem, "options": opts, "answer": sorted(ans), "explain": ex}
    def YN(lesson, obj, diff, stem, sts, ex, case=None):
        return {**base(lesson, obj, diff, "yesno", case), "stem": stem, "statements": [{"s": s, "a": a} for s, a in sts], "explain": ex}
    def O(lesson, obj, diff, stem, steps, ex):
        return {**base(lesson, obj, diff, "order"), "stem": stem, "options": steps, "explain": ex}
    return S, M, YN, O

