def write(name, domain, qs):
    path = os.path.join(HERE, "..", "parts", "secai-plus", name)
    json.dump({"exam": "secai-plus", "domain": domain, "lessons": [], "questions": balance(qs, seed=name)},
              open(path, "w"), indent=1, ensure_ascii=False)
    print(name, len(qs))

